static const float quality = 5;
static float depth = q29*4;
float3 rsl, rsl2, rsl3, ret1, screen3, back, neu2;
float2 dz, uv0, uv1, uv2, uv4, rsk, dz1,tmp2, Kugel1;
float  lprof, gmask, tile,dist, tower;
static float lav_gnd = 0;
static float2 mov = float2 (q5,q6);

static float3 t = float3(q14, q15,q16);
static float3 s = float3(q17,q18,q19);
static float3 ts = -cross(s,t);
static float3 pos = float3 (q11,q12,q13);

float3 project (float dist) {  float z;
  z = dist/mul(cross(ts,-t),screen3) *(1-lav_gnd);
  gmask = (z >= -3) * (z <= 0);
  return gmask * float3(mul(float2x3(ts,t),cross(pos,screen3))*z,-z);}

shader_body {uv0 = uv;
screen3 = float3 ((uv-.5)*aspect.xy,1) * (1+.0*tex2D (sampler_noise_hq,uv+time*.1));//wirkt wie zoom / Tele ###

dist = .5; lav_gnd = 0; tower = 1; 
for (int m=1; m <= quality; m++) {
  rsl = project (dist)+float3 (mov,0);
  lprof =  (tex2D (sampler_pw_noise_lq,rsl.xy*.1).r <=.7); 
  uv2 = rsl.xy*.4*64;
  tile = saturate(2-3*max(abs(frac(uv2.x)-.5),abs(frac(uv2.y)-.5)))*.25+.75;
  lprof = 1-saturate(1-lprof)*tile;
  lprof *= tex2D (sampler_pw_noise_lq,rsl.xy*.1/16+tower).r;
  lav_gnd -= lprof/quality*depth/rsl.z* (1+tex2D (sampler_pw_noise_lq,rsl.xy*.02).g*.2); 
  tower -= lprof/quality/2 ; 
} 
rsl = project (dist)+float3 (mov,0); 
float step = int(time*8)%14+q24;
