mask *=              tex2D(sampler_pw_noise_lq,rsl.xy + 1.0/8*int(tower*8)).r >= .89;
float3 windows = pow(tex2D(sampler_pw_noise_lq,rsl.xy),2).r * !mask ;


uv2 = rsl.xy*4*64;
tile = saturate(1-2*max(abs(frac(uv2.x)-.5),abs(frac(uv2.y)-.5)));
windows *= tile*GetPixel(frac(rsl.xy*2));

