float3 light = GetPixel(frac(rsl2));
ret1 =  lerp(8*light*saturate(1-tower),2*windows *(tower*2-1),saturate(2*tower-1.1)) ;

uv4 = float2(frac(rsl.x),frac(rsl.y));
ret1 *= 1+pow(sin(2*(uv4.x/uv4.y)+8*time),8) *(q28%3==1)* roam_sin ;;  

